11.         public string BuildReport(DateTime businessDate, ReconciliationResult result)
12.         {
13.             var report = new StringBuilder();
14.             report.AppendLine("Legacy Trade Reconciliation - End Of Day Report");
15.             report.AppendLine("Business Date: " + businessDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture));
16.             report.AppendLine();
17.             report.AppendLine("Totals");
18.             report.AppendLine("------");
19.             report.AppendLine("Trades Read: " + result.TotalTradesRead);
20.             report.AppendLine("Canonical Trades: " + result.CanonicalTradeCount);
21.             report.AppendLine("Matched: " + result.MatchedCount);
22.             report.AppendLine("Manual Override Matched: " + result.ManualOverrideMatchedCount);
23.             report.AppendLine("Manual Override Suppressed: " + result.ManualOverrideSuppressedCount);
24.             report.AppendLine("Open Breaks: " + result.OpenBreaks.Count);
25.             report.AppendLine("Duplicate Trades: " + result.DuplicateTradeCount);
26.             report.AppendLine("Stale Overrides: " + result.StaleOverrides.Count);
27.             report.AppendLine();
28.             report.AppendLine("Open Break Reasons");
29.             report.AppendLine("------------------");
30. 
31.             var reasonCounts = result.OpenBreaks
32.                 .SelectMany(record => record.Reasons.Split('|'))
33.                 .Select(reason => reason.Trim())
34.                 .Where(reason => !string.IsNullOrWhiteSpace(reason))
35.                 .GroupBy(reason => reason, StringComparer.Ordinal)
36.                 .OrderBy(group => group.Key, StringComparer.Ordinal);
37. 
38.             foreach (var reasonCount in reasonCounts)
39.             {
40.                 report.AppendLine(reasonCount.Key + ": " + reasonCount.Count());
41.             }
42. 
43.             if (!reasonCounts.Any())
44.             {
45.                 report.AppendLine("None");
46.             }
47. 
48.             if (result.StaleOverrides.Any())
49.             {
50.                 report.AppendLine();
51.                 report.AppendLine("Stale Overrides");
52.                 report.AppendLine("---------------");
53. 
54.                 foreach (var staleOverride in result.StaleOverrides.OrderBy(item => item.TradeId, StringComparer.Ordinal))
55.                 {
56.                     report.AppendLine(staleOverride.TradeId + ": " + staleOverride.Action + " (" + staleOverride.ApprovedBy + ")");
57.                 }
58.             }
59. 
60.             return report.ToString().TrimEnd() + Environment.NewLine;
61.         }
62.     }
63. }
