void Assert(bool condition, string message)
{
    if (!condition)
    {
        throw new InvalidOperationException(message);
    }
}

void RunSafetyScenario()
{
    var engine = new MatchingEngine();

    var trades = new[]
    {
        new TradeRecord { TradeId = " t-1 ", Account = " acc-1 ", Instrument = " ibm.n ", Quantity = 100m, SettlementDate = new DateTime(2025, 3, 17), Currency = " usd ", NetAmount = 12500m },
        new TradeRecord { TradeId = "T-1", Account = "ACC-1", Instrument = "IBM.N", Quantity = 100m, SettlementDate = new DateTime(2025, 3, 17), Currency = "USD", NetAmount = 12500m },
    };

    var positions = new[]
    {
        new PositionRecord { PositionId = "P-1", Account = "ACC-1", Instrument = "IBM.N", Quantity = 100m, SettlementDate = new DateTime(2025, 3, 17), Currency = "USD" }
    };

    var settlements = new[]
    {
        new SettlementRecord { SettlementId = "S-1", Account = "ACC-1", Instrument = "IBM.N", Quantity = 100m, SettlementDate = new DateTime(2025, 3, 17), Currency = "USD", CashAmount = 12500m }
    };

    var overrides = new List<ManualOverrideRecord>();
    var result = engine.Reconcile(trades, positions, settlements, overrides);
    Assert(result.OpenBreaks.Count == 1, "duplicate trade should break");
    Assert(result.OpenBreaks[0].TradeId == "T-1", "duplicate trade should retain canonical id");
    Assert(result.DuplicateTradeCount == 1, "duplicate count should be 1");

    var overrideResult = engine.Reconcile(new[]
    {
        new TradeRecord { TradeId = "T-2", Account = "ACC-2", Instrument = "VOD.L", Quantity = 100m, SettlementDate = new DateTime(2025, 3, 17), Currency = "GBP", NetAmount = 12000m }
    },
    new[]
    {
        new PositionRecord { PositionId = "P-2", Account = "ACC-2", Instrument = "VOD.L", Quantity = 100m, SettlementDate = new DateTime(2025, 3, 17), Currency = "GBP" }
    },
    new[]
    {
        new SettlementRecord { SettlementId = "S-2", Account = "ACC-2", Instrument = "VOD.L", Quantity = 100m, SettlementDate = new DateTime(2025, 3, 17), Currency = "EUR", CashAmount = 12000m }
    },
    new[]
    {
        new ManualOverrideRecord { TradeId = "T-2", Action = "ForceMatch", Note = "override", ApprovedBy = "ops" }
    });

    Assert(overrideResult.MatchedTrades.Count == 1, "override should resolve a concrete break");
    Assert(overrideResult.StaleOverrides.Count == 0, "override should not be stale");

    var staleResult = engine.Reconcile(new[]
    {
        new TradeRecord { TradeId = "T-3", Account = "ACC-3", Instrument = "MSFT.OQ", Quantity = 100m, SettlementDate = new DateTime(2025, 3, 17), Currency = "USD", NetAmount = 1000m }
    },
    new PositionRecord[0],
    new SettlementRecord[0],
    new[]
    {
        new ManualOverrideRecord { TradeId = "T-3", Action = "ForceMatch", Note = "", ApprovedBy = "ops" }
    });

    Assert(staleResult.MatchedTrades.Count == 0, "invalid override should not match");
    Assert(staleResult.StaleOverrides.Count == 1, "invalid override should be stale");

    Console.WriteLine("safety scenarios passed");
}

try
{
    RunSafetyScenario();
}
catch (Exception ex)
{
    Console.WriteLine(ex.Message);
    Environment.Exit(1);
}

